<script setup>
import {shallowRef,watch,nextTick,onUnmounted,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {modal,closeModal,session,login,logout,requestModeSwitch} from '../session'
import {navGroups,path,fmt} from '../data'
import Icon from './Icon.vue'
import {locale,languages,applyLocale,t} from '../i18n'
import Coin from './Coin.vue'
const dialog=shallowRef(null),current=shallowRef(null),closing=shallowRef(false),amount=shallowRef(''),error=shallowRef(''),done=shallowRef(false),expanded=shallowRef(''),message=shallowRef('')
const route=useRoute(),router=useRouter();let trigger,previousOverflow,closeTimer,returnFocus
const isDrawer=computed(()=>current.value?.type==='menu')
const formType=computed(()=>['subscribe','donate','order','convert','loan','c2c'].includes(current.value?.type))
const estimate=computed(()=>Number(amount.value||0)*Number(current.value?.data.rate||0)/100*Math.max(1,Number(current.value?.data.days||1)))
watch(modal,async(value)=>{if(!value)return;current.value=value;amount.value=String(value.data.amount||'');error.value='';done.value=false;closing.value=false;expanded.value='';message.value=value.data.value||'';trigger=document.activeElement;returnFocus=value.data.returnFocus;previousOverflow=document.body.style.overflow;await nextTick();dialog.value.showModal();document.body.style.overflow='hidden';await nextTick();dialog.value.querySelector((value.data.modeSwitch||value.data.focusCancel)?'[data-cancel]':'[data-initial-focus]')?.focus()})
function cleanup(){document.body.style.overflow=previousOverflow??'';if(trigger?.isConnected)trigger.focus();else returnFocus?.();clearTimeout(closeTimer)}
function close(afterClose){if(closing.value||!current.value)return;closing.value=true;closeTimer=setTimeout(()=>{dialog.value?.close();current.value=null;closeModal();closing.value=false;cleanup();if(typeof afterClose==='function')afterClose()},matchMedia('(prefers-reduced-motion: reduce)').matches?0:150)}
function cancel(e){e.preventDefault();if(amount.value&&!done.value){error.value="overlay.ui.unsavedContentUseCloseOrCancelToLeave";return}close()}
function changeLanguage(l){applyLocale(l);close();}
function accountAction(){if(done.value||closing.value)return;if(current.value.type==='account-edit'){if(!message.value.trim()){error.value="profile.enterUsername";return}current.value.data.onSave?.(message.value.trim())}else current.value.data.onConfirm?.();done.value=true;close()}
function switchFromMenu(mode){
  if(mode===session.mode||closing.value)return
  const from=route.fullPath
  close(()=>{if(route.fullPath===from)requestModeSwitch(mode)})
}
function navigate(to){close();router.push(path(to))}
function createdOrder(data,val){
 const price=Number(data.price),quantity=Number((val*(data.kind==='futures'?data.leverage||1:1)/price).toFixed(6)),pending=['openOrders','spotOpenOrders'].includes(data.bucket)
 return {id:crypto.randomUUID(),price,markPrice:data.markPrice||price,quantity,filledQuantity:pending?0:quantity,leverage:data.leverage||1,margin:val,notional:price*quantity,fee:pending?0:Number((price*quantity*.0005).toFixed(2)),orderType:data.orderType,recordStatus:pending?'trade.current.pending':'trade.filled'}
}
function submit(){if(done.value)return;const val=Number(amount.value),min=current.value.data.min??0.01;if(!Number.isFinite(val)||val<min){error.value={key:'overlay.amountMinimum',params:{amount:fmt(min)}};return}if(val>(current.value.data.max??500000)){error.value="trade.spotErrorAboveMaxNotional";return}if(session.mode!=="common.demo.demo"&&current.value.type!=='loan'){error.value="overlay.ui.insufficientBalanceSwitchToDemoToTryThisLocally";return}if(val>100000){error.value="assets.withdraw.error.insufficientBalance";return}error.value='';done.value=true;current.value.data.onConfirm?.(val);if(current.value.type==='subscribe')session.subscriptions.push({name:current.value.data.name,amount:val,status:"aiQuant.myStrategies.summary.running"});if(current.value.type==='order')session.orders.push({...createdOrder(current.value.data,val),name:current.value.data.name,amount:val,symbol:current.value.data.symbol||'USD',side:current.value.data.side,kind:current.value.data.kind,marketName:current.value.data.marketName,bucket:current.value.data.bucket,direction:current.value.data.direction,createdAt:Date.now(),settled:false,status:"overlay.ui.createdDemo"});amount.value=''}
function keydown(e){if(e.key!=='Tab')return;const els=[...dialog.value.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select,textarea,[tabindex="0"]')].filter(x=>x.getClientRects().length);if(!els.length){e.preventDefault();return}const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
watch(()=>route.fullPath,()=>{if(current.value)close()})
onUnmounted(()=>{dialog.value?.close();cleanup()})
</script>
<template><dialog ref="dialog" class="nt-dialog" :class="{drawer:isDrawer,closing,video:current?.type==='video','mode-confirm':current?.data.modeSwitch}" aria-labelledby="overlay-title" @cancel="cancel" @keydown="keydown"><template v-if="current"><header class="overlay-header"><h2 id="overlay-title" tabindex="-1" data-initial-focus>{{ $t(current.title) }}</h2><button class="overlay-close" :aria-label="$t(&quot;aiQuant.detail.close&quot;)" @click="close">×</button></header><div class="overlay-body">
<template v-if="isDrawer"><nav class="drawer-nav"><RouterLink :to="path('/')" @click="close">{{ $t("common.home") }}</RouterLink><div v-for="g in navGroups" :key="g.label"><button :aria-expanded="expanded===g.label" @click="expanded=expanded===g.label?'':g.label">{{ $t(g.label) }}<Icon name="chevron-down"/></button><div v-if="expanded===g.label" class="drawer-subnav"><RouterLink v-if="g.path" :to="path(g.path)" @click="close">{{ $t("aiQuant.landing.eyebrow") }}</RouterLink><RouterLink v-for="item in g.items" :key="item[0]" :to="path(item[2])" @click="close">{{ $t(item[0]) }}<small>{{ $t(item[1]) }}</small></RouterLink></div></div><RouterLink :to="path('/news')" @click="close">{{ $t("common.news") }}</RouterLink><RouterLink :to="path('/charity')" @click="close">{{ $t("common.charity") }}</RouterLink></nav><div class="drawer-account"><div v-if="session.loggedIn" class="mode-toggle"><button v-for="m in [&quot;common.demo.real&quot;,&quot;common.demo.demo&quot;]" :key="m" :class="{active:session.mode===m}" :aria-pressed="session.mode===m" @click="switchFromMenu(m)">{{ $t(m) }}</button></div><button class="primary-button wide-button" @click="navigate(session.loggedIn?'/assets':'/login')">{{ $t(session.loggedIn?"assets.pageTitle":"auth.login") }}</button><button class="secondary-button wide-button" @click="navigate('/profile')">{{ $t("common.profile") }}</button><button v-if="session.loggedIn" @click="logout();close()">{{ $t("profile.logout") }}</button></div><p class="muted">{{ $t("common.language") }}</p><div class="language-list"><button v-for="[code,name] in languages" :key="code" @click="changeLanguage(code)">{{ $t(name) }}<Icon v-if="locale===code" name="check" green/></button></div></template>
<template v-else-if="current.type==='video'"><p class="muted">{{ $t("aiQuant.howItWorks.description") }}</p><video controls playsinline preload="metadata" src="/newtrend/assets/ai-quant.mp4" :aria-label="$t(&quot;home.aiQuantFilm.title&quot;)" @error="error=&quot;overlay.ui.videoFailedToLoadTryAgainLater&quot;"></video></template>
<template v-else-if="current.type==='language'"><div class="language-list"><button v-for="[code,name] in languages" :key="code" @click="changeLanguage(code)">{{ $t(name) }}<Icon v-if="locale===code" name="check" green/></button></div></template>
<template v-else-if="current.type==='support'"><p class="muted">{{ $t("overlay.ui.welcomeToNewquantcapitalSupport") }}</p><div class="card section-gap"><p>{{ $t("customerService.welcomeMessage") }}</p></div><form class="form-stack section-gap" @submit.prevent="done=true"><label>{{ $t("overlay.ui.message") }}<textarea v-model="message" rows="4" :placeholder="$t(&quot;overlay.ui.describeYourIssue&quot;)" required></textarea></label><button class="primary-button" :disabled="!message.trim()||done">{{ $t("customerService.send") }}</button><p class="notice">{{ $t("overlay.ui.messagesAreNotSentToTheOriginalSupportTeam") }}</p><p v-if="done" role="status" class="positive">{{ $t("overlay.ui.demoMessageShownLocallyNothingWasSent") }}</p></form></template>
<template v-else-if="current.type==='wallet'"><p class="notice">{{ $t("overlay.ui.thisLocalDemoDoesNotRequestWalletPermissionsOr") }}</p><button class="primary-button wide-button section-gap" @click="login();done=true" :disabled="done">{{ $t("overlay.ui.connectDemoWallet") }}</button><p v-if="done" role="status" class="positive section-gap">{{ $t("overlay.ui.localDemoAccountConnected") }}</p></template>
<template v-else-if="current.type==='messages'"><div class="empty"><Icon name="mail"/><p>{{ $t("overlay.ui.noNewMessages") }}</p></div></template>
<template v-else-if="current.type==='account-edit'"><form id="account-action" class="form-stack" @submit.prevent="accountAction"><label>{{ $t(current.title) }}<input v-model="message" maxlength="60" :aria-label="$t(current.title)"/></label></form></template>
<template v-else-if="current.type==='account-confirm'"><p class="muted">{{ $t(current.data.description) }}</p><form id="account-action" @submit.prevent="accountAction"></form></template>
<template v-else-if="current.type==='vip'"><div class="card"><small>{{ $t("profile.vip.currentTierLabel") }}</small><p class="metric">{{ $t("VIP 0") }}</p><p class="muted">{{ $t("overlay.ui.100000UsdMoreToReachVip1") }}</p></div><h3 class="section-gap">{{ $t("profile.vip.tiersLabel") }}</h3><div v-for="(amount,index) in [0,100000,500000,1000000,5000000,10000000]" :key="index" class="summary-line" style="padding:16px 0;border-bottom:1px solid #ffffff0b"><strong>{{ $t("VIP ") }}{{ $t(index) }}</strong><span>{{ $t(fmt(amount)) }}{{ $t(" USD") }}</span></div></template>
<template v-else-if="formType"><div v-if="current.data.name" class="summary-line product-summary"><div class="coin-label"><Coin :symbol="current.data.symbol||'USD'"/><div><strong>{{ $t(current.data.name) }}</strong><small class="muted" style="display:block;margin-top:6px">{{ $t(current.data.symbol||'USD') }} · {{ (current.data.days ? $t('common.durationDays', {count: current.data.days}) : $t('aiQuant.quantFund.card.termFlexible')) }}</small></div></div><span v-if="current.data.rate" class="metric">{{ $t(current.data.rate) }}%</span></div><form id="action-form" class="form-stack" @submit.prevent="submit"><div class="summary-line"><label for="action-amount">{{ $t(current.type==='order'?"overlay.ui.orderQuantity":"earn.subscribe.amountLabel") }}</label><small class="muted">{{ $t("aiQuant.create.availableBalanceLabel") }}{{ $t(session.mode==="common.demo.demo"?'100,000':'0') }} {{ $t(current.data.symbol||'USD') }}</small></div><input id="action-amount" v-model="amount" inputmode="decimal" :placeholder="$t(&quot;c2c.order.fiatAmountPlaceholder&quot;)" :aria-invalid="Boolean(error)" aria-describedby="action-error" :disabled="done"/><small class="muted">{{ $t("earn.table.columns.minAmount") }}{{ $t(fmt(current.data.min??.01)) }} {{ $t(current.data.symbol||'USD') }}{{ $t("overlay.ui.localSimulation") }}</small><div class="card"><small class="muted">{{ $t(current.type==='order'?"overlay.ui.orderSummary":"earn.subscribe.estReward") }}</small><p style="margin-top:12px">{{ $t(current.type==='order'?(current.data.description||current.data.name):amount?fmt(estimate)+' '+(current.data.symbol||'USD'):"earn.subscribe.estRewardEmpty") }}</p><div v-if="current.data.days" class="timeline"><div><small>{{ $t("aiQuant.quantFund.detail.flowStep1Title") }}</small>{{ $t("earn.timeline.values.now") }}</div><div><small>{{ $t("earn.timeline.steps.accrualStart") }}</small>{{ $t("earn.timeline.values.afterReview") }}</div><div><small>{{ $t("aiQuant.strategies.fields.endDate") }}</small>{{ $t(current.data.days) }}{{ $t("overlay.ui.daysLater") }}</div></div></div><p v-if="done" class="form-success" role="status">{{ $t("overlay.ui.demoCompletedNoRealTransactionWasSent") }}</p></form></template>
<template v-else><p class="muted">{{ $t(current.data.description||"overlay.ui.localInterfaceDemoNotConnectedToTheOriginalAccount") }}</p></template>
<p v-if="error" id="action-error" class="form-error section-gap" role="alert">{{ $t(error) }}</p>
</div><footer v-if="!isDrawer&&current.type!=='video'" class="overlay-footer"><button class="secondary-button" data-cancel @click="close">{{ $t(done?"aiQuant.detail.close":"aiQuant.create.cancel") }}</button><button v-if="['account-edit','account-confirm'].includes(current.type)" class="primary-button" form="account-action" type="submit" :disabled="done||closing">{{ $t(current.data.confirmLabel||"earn.redeem.success.done") }}</button><button v-if="formType" class="primary-button" form="action-form" :disabled="done||!amount" type="submit">{{ $t(done?"assets.statusCompleted":current.type==='order'?"overlay.ui.confirmOrder":"earn.redeem.success.done") }}</button></footer></template></dialog></template>
<style scoped>
.nt-dialog{margin:auto;padding:0;width:min(512px,calc(100vw - 32px));max-height:calc(100vh - 32px);max-height:calc(100dvh - 32px);border:1px solid #ffffff12;border-radius:18px;background:#090d12;color:#fff;overflow:hidden;box-shadow:0 24px 100px #0008}.nt-dialog[open]{display:flex;flex-direction:column;animation:modal-in 200ms ease-out}.nt-dialog::backdrop{background:#0009;backdrop-filter:blur(7px);animation:fade-in 200ms ease-out}.nt-dialog.closing{animation:modal-out 150ms ease-in forwards}.nt-dialog.closing::backdrop{animation:fade-out 150ms ease-in forwards}.nt-dialog.video{width:min(768px,calc(100vw - 32px))}.overlay-header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 16px 8px 24px;flex-shrink:0}.overlay-header h2{font-size:1.125rem;line-height:1.5;overflow-wrap:anywhere}.overlay-close{width:44px;height:44px;border-radius:50%;font-size:1.625rem;flex-shrink:0;color:#fff9}.overlay-body{overflow-y:auto;overscroll-behavior:contain;padding:8px 24px 24px;min-height:0;scroll-padding:24px;padding-bottom:max(24px,env(safe-area-inset-bottom))}.overlay-body video{display:block;width:100%;aspect-ratio:16/9;margin-top:16px;border-radius:16px;background:#202226}.overlay-footer{display:flex;justify-content:flex-end;gap:16px;padding:16px 24px;flex-shrink:0;border-top:1px solid #ffffff08;padding-bottom:max(16px,env(safe-area-inset-bottom))}.product-summary{padding:8px 0 24px;border-bottom:1px solid #ffffff0c;margin-bottom:24px}.product-summary .metric{font-size:1.25rem}.language-list{display:grid;gap:4px}.language-list button{display:flex;align-items:center;justify-content:space-between;padding:16px 12px;text-align:left;border-radius:12px}.language-list button:hover{background:#ffffff08}.drawer{margin:0 auto 0 0;height:100vh;height:100dvh;max-height:100vh;max-height:100dvh;width:min(288px,calc(100vw - 48px));border-radius:0;background:#121415;padding-left:env(safe-area-inset-left)}.drawer[open]{animation:drawer-in 200ms ease-out}.drawer.closing{animation:drawer-out 150ms ease-in forwards}.drawer .overlay-header{padding:8px 8px 8px 20px;border-bottom:1px solid #ffffff05}.drawer .overlay-body{padding:8px 16px 24px}.drawer-nav>a,.drawer-nav>div>button{display:flex;justify-content:space-between;align-items:center;width:100%;text-align:left;padding:14px 4px}.drawer-subnav a{display:block;padding:12px 16px;font-size:0.875rem}.drawer-subnav small{display:block;color:#fff6;font-size:0.6875rem;margin-top:4px}.drawer-account{display:grid;gap:14px;margin:32px 0 24px}.drawer-account .mode-toggle{justify-content:center}.drawer-account .mode-toggle button{flex:1}.drawer-account .primary-button{padding:9px 20px}@keyframes modal-in{from{opacity:0;transform:scale(.96)}to{opacity:1;transform:scale(1)}}@keyframes modal-out{to{opacity:0;transform:scale(.96)}}@keyframes fade-in{from{opacity:0}to{opacity:1}}@keyframes fade-out{to{opacity:0}}@keyframes drawer-in{from{transform:translateX(-100%)}to{transform:translateX(0)}}@keyframes drawer-out{to{transform:translateX(-100%)}}@media(prefers-reduced-motion:reduce){.nt-dialog[open],.drawer[open]{animation:fade-in 40ms linear}.nt-dialog.closing,.drawer.closing{animation:fade-out 40ms linear}}
.mode-confirm .overlay-header{padding:12px 8px 0 24px}.mode-confirm .overlay-body{padding:0 24px 8px;line-height:1.6}.mode-confirm .overlay-footer{border-top:0;padding:8px 24px 24px}.mode-confirm .overlay-footer button{padding:9px 16px;border-radius:999px}.mode-confirm .secondary-button{background:#202326;border-color:transparent}.mode-confirm .overlay-header h2{font-size:1.125rem}
</style>
